#pop-up-bg {
  position: absolute;
  top: 0px;
  left: 0px;
  background: rgba(141, 172, 172, 0.4509803922);
  height: 100vh;
  width: 100vw;
}

#pop-up {
  background: white;
  height: calc(100vw - 15px);
  width: calc(100vw - 15px);
  padding: 10px;
}
#pop-up .img-container-wrapper {
  height: calc((100vw - 15px) / 3);
  width: 100%;
  position: relative;
}
#pop-up .img-container-wrapper #click-here {
  position: absolute;
  top: 35%;
  left: 15%;
  height: 50px;
  width: 50px;
  transform: rotate(15deg);
  z-index: 5;
}
#pop-up .img-container-wrapper .img-container {
  width: calc((100vw - 15px) / 3);
  height: calc((100vw - 15px) / 3);
  overflow: hidden;
  border-radius: 1000px;
  animation: color-pulse-blue 5s linear infinite;
}
#pop-up .img-container-wrapper .img-container #page-icon {
  object-fit: cover;
  width: 100%;
}
#pop-up .img-container-wrapper .img-container:active {
  border: 3px solid black !important;
}
#pop-up .exit-btn-container {
  /* position: absolute; */
  width: 100%;
  overflow: hidden;
}
#pop-up .exit-btn-container .exit-btn {
  margin: 0px 7px;
}
#pop-up p {
  overflow: hidden scroll;
  height: calc((100vw - 15px) / 3 + 10px);
}

nav {
  width: 100vw;
  height: 50px;
  /* border: 1px solid green; */
  background: #5c5c5c;
}
nav .nav-btn {
  /* margin: 10px 15px; */
  /* background: $nav-btn-color; */
  /* @extend .bg-primary; */
  color: white;
  /* height: 100%; */
  height: 30px;
  width: 100px;
  border-radius: 5px;
}
nav .nav-btn.active {
  border: 3px solid white;
}
nav .nav-btn.dropdown {
  /* position: relative; */
}
nav .nav-btn.dropdown .dropdown-list {
  transform-origin: 0% 0%;
  position: absolute;
  width: 100vw;
  top: 50px;
  left: 0px;
  z-index: 10;
}
nav .nav-btn.dropdown.opened .dropdown-list {
  animation: grow-down 0.5s linear;
  /* display: block; */
}
nav .nav-btn.dropdown.closed .dropdown-list {
  animation: shrink-up 0.5s linear forwards;
}
nav .nav-btn.dropdown.loaded .dropdown-list {
  display: none;
}
nav .nav-btn.dropdown:after {
  content: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='10' height='10' fill='white' class='bi bi-chevron-down' viewBox='0 0 16 10'><path fill-rule='evenodd' d='M1.646 4.646a.5.5 0 0 1 .708 0L8 10.293l5.646-5.647a.5.5 0 0 1 .708.708l-6 6a.5.5 0 0 1-.708 0l-6-6a.5.5 0 0 1 0-.708'/></svg>");
}
nav .nav-btn.dropdown.opened:after {
  content: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='10' height='16' fill='white' class='bi bi-chevron-up' viewBox='0 0 16 10'><path fill-rule='evenodd' d='M7.646 4.646a.5.5 0 0 1 .708 0l6 6a.5.5 0 0 1-.708.708L8 5.707l-5.646 5.647a.5.5 0 0 1-.708-.708z'/></svg>");
}
nav .nav-btn.dropdown.opened {
  transition: content 0.5s;
}
nav .nav-btn.dropdown a {
  /* background: darken($nav-btn-color, 30%); */
  height: 45px;
  width: 100%;
}
nav .nav-btn.dropdown a:not(:last-child) {
  border-bottom: 1px solid #1c1c1c;
}
nav .nav-btn.dropdown a:not(:last-child).active {
  /* background: white; */
  color: black;
  font-weight: bold;
}
nav .nav-btn.dropdown a:not(:last-child):active {
  background: black;
}
nav .nav-btn:active {
  background: black;
}

