  }
  25% {
    transform: translate(62vw, -26vh);
  }
  50% {
    transform: translate(73vw, -23vh);
  }
  75% {
    transform: translate(50vw, -85vh);
  }
  100% {
    transform: translate(71vw, -95vh);
  }
}
