@media (orientation: landscape) {
  #pop-up {
    background: white;
    height: 100vh;
    width: 100vh;
    padding: 10px;
  }
  #pop-up .img-container-wrapper {
    height: 33.3333333333vh;
    width: 100%;
    position: relative;
  }
  #pop-up .img-container-wrapper #click-here {
    position: absolute;
    top: 35%;
    left: 15%;
    height: 50px;
    width: 50px;
    transform: rotate(15deg);
    z-index: 5;
  }
  #pop-up .img-container-wrapper .img-container {
    width: 33.3333333333vh;
    height: 33.3333333333vh;
    overflow: hidden;
    border-radius: 1000px;
    animation: color-pulse-blue 5s linear infinite;
  }
  #pop-up .img-container-wrapper .img-container #page-icon {
    object-fit: cover;
    width: 100%;
  }
  #pop-up .img-container-wrapper .img-container:active {
    border: 3px solid black !important;
  }
  #pop-up .exit-btn-container {
    /* position: absolute; */
    width: 100%;
    overflow: hidden;
  }
  #pop-up .exit-btn-container .exit-btn {
    margin: 0px 7px;
  }
  #pop-up p {
    overflow: hidden scroll;
    height: calc(33.3333333333vh + 10px);
  }
}
